head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > P > msaName]<br/>MSA 기능을 활성화 하기 위해 MSA Server 의 이름을 설정합니다.",
    "validation" : [
        "name MSA Server 의 이름을 설정합니다.",
        "설정값은 config.xml 의 msaServer 항목에 존재하는 값이어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    scwin.btn_getObj_onclick();
}



scwin.btn_getObj_onclick = function (e) {
    let objImage1 = document.querySelector('img[id*=target1]');

    wf_body_bottom.getObj("scwin").setReturnValue("image1 요청 URL : " + objImage1.src);
}
